    async function runTranscript(){ if(!state.lastUrl){setStatus(els.aiStatus,"先解析一条视频，再识别口播文案。","err");return;} setStatus(els.aiStatus,"正在提取视频音轨并调用小米语音识别，请稍候..."); try{const data=await api("/api/v1/ai/transcript",{method:"POST",body:JSON.stringify({url:state.lastUrl})}); state.lastTranscript=data.transcript||""; const real=data.provider==="xiaomi_asr"; const source=real?"小米 MiMo-V2.5-ASR（真实音频识别）":"元数据草稿（后台未开启 ASR）"; els.aiResult.textContent=[real?"真实口播文本：":"口播草稿：",data.transcript,"","标题："+(data.title||"--"),"来源："+source,data.duration_seconds!==null&&data.duration_seconds!==undefined?("音频时长："+data.duration_seconds+" 秒"):"","下一步：可点击“按提示改写”，系统会把这份口播原文交给文字模型。"].filter(Boolean).join("\n"); if(!els.aiPrompt.value)els.aiPrompt.value="请基于识别出的真实口播原文改写，保留原视频情绪和关键信息，表达更自然。"; setStatus(els.aiStatus,real?"真实口播识别完成，可继续改写。":"后台未开启 ASR，当前返回元数据草稿。","ok");}catch(err){setStatus(els.aiStatus,err.message||String(err),"err");} }
