    async function downloadCurrentComments(type){ const q=state.currentAwemeId?("aweme_id="+encodeURIComponent(state.currentAwemeId)):(state.lastUrl?("url="+encodeURIComponent(state.lastUrl)):""); if(!q){setStatus(els.commentsStatus,"\u5148\u89e3\u6790\u6216\u9884\u89c8\u4e00\u6761\u89c6\u9891\u3002","err");return;} try{const headers=new Headers(); if(state.vipToken)headers.set("authorization","Bearer "+state.vipToken); const res=await fetch("/api/v1/comments/export?"+q+"&count=100&type="+encodeURIComponent(type),{headers:headers}); if(!res.ok){const err=await res.json().catch(function(){return null;}); throw new Error(friendlyError((err&&err.error&&err.error.detail)||(err&&err.message)||("HTTP "+res.status)));} const blob=await res.blob(); const cd=res.headers.get("content-disposition")||""; const m=cd.match(/filename="([^"]+)"/); const a=document.createElement("a"); a.href=URL.createObjectURL(blob); a.download=m?m[1]:"comments."+(type==="csv"?"csv":"json"); document.body.appendChild(a); a.click(); setTimeout(function(){URL.revokeObjectURL(a.href);a.remove();},1000); setStatus(els.commentsStatus,"\u5df2\u5f00\u59cb\u5bfc\u51fa\u5f53\u524d\u8bc4\u8bba\u3002","ok");}catch(err){setStatus(els.commentsStatus,err.message||String(err),"err");} }
