    els.parseBtn.addEventListener("click",function(){parseLink(els.input.value,"manual");}); els.clearBtn.addEventListener("click",function(){els.input.value="";state.lastUrl="";state.lastData=null;state.lastTranscript="";setStatus(els.status,"已清空，等待链接输入。");}); els.input.addEventListener("input",debounce(function(){ if(extractDouyinUrl(els.input.value))parseLink(els.input.value,"input"); },650)); document.addEventListener("paste",function(event){const text=(event.clipboardData&&event.clipboardData.getData("text"))||""; if(extractDouyinUrl(text)){els.input.value=text;setTimeout(function(){parseLink(text,"paste");},30);}}); els.clipboardBtn.addEventListener("click",async function(){state.clipboardWatch=true;els.clipboardBtn.textContent="识别中";await scanClipboard();}); async function scanClipboard(){if(!state.clipboardWatch||!navigator.clipboard||!navigator.clipboard.readText)return;try{const text=await navigator.clipboard.readText();if(extractDouyinUrl(text)){els.input.value=text;await parseLink(text,"clipboard");}}catch{}} window.addEventListener("focus",scanClipboard); setInterval(scanClipboard,4500); async function pingOnline(){const client_id=localStorage.getItem("online_client_id")||(crypto.randomUUID?crypto.randomUUID():String(Date.now())+Math.random());localStorage.setItem("online_client_id",client_id);try{const data=await api("/api/v1/online/ping",{method:"POST",body:JSON.stringify({client_id})});els.onlineCount.textContent=data.online_count;}catch{els.onlineCount.textContent="--";}} setInterval(pingOnline,15000); pingOnline();
    function renderMember(data){ const plan=data.member&&data.member.plan; els.vipState.textContent=data.activated?(data.member?("已登录 · "+data.member.username):"已激活"):"未登录"; els.vipState.className="pill"+(data.activated?" success":""); els.memberBenefits.textContent=plan?(AI_FEATURE_ENABLED?("套餐："+plan.name+" · 批量上限 "+plan.batch_parse_limit+" · AI "+plan.ai_daily_quota+"/日 · 并发 "+plan.concurrency+" · 优先级 "+plan.queue_priority):("套餐："+plan.name+" · 批量上限 "+plan.batch_parse_limit+" · 并发 "+plan.concurrency+" · 优先级 "+plan.queue_priority)):(AI_FEATURE_ENABLED?"单条解析、主页预览、本地口播和当前评论预览可直接使用；批量解析/批量文案/批量导出需会员。":"单条解析、主页预览和当前评论预览可直接使用；批量解析与批量导出需会员。"); if(plan){ els.batchCount.max=plan.batch_parse_limit; els.batchConcurrency.max=plan.concurrency; if(els.queuePriority)els.queuePriority.textContent=plan.queue_priority; } }
